<script setup>
import {computed,inject,ref} from 'vue';
import I from './Icon.vue';
import Modal from './Modal.vue';
import AssetPicker from './AssetPicker.vue';
import WordLimit from './WordLimit.vue';
import BrainTranscriptReview from './BrainTranscriptReview.vue';
import {call,pickFiles} from '../api';
import {profileShareLink,brainCollectionUnavailable} from '../../server/share-link.mjs';
const {state,draft:d,busy,act,notify,refresh,save,navigate}=inject('studio');
const externalCollection=computed(()=>!!String(state.value.settings?.provider?.brainUrl||'').trim());
const localCollection=computed(()=>state.value.brainCollection?.local===true);
const collectionConfigured=computed(()=>externalCollection.value||localCollection.value);
const sampleLimit=computed(()=>state.value.brainCollection?.sampleLimits?.[d.value.brain.mode]||(d.value.brain.mode==='deep'?6:3));
const profileLink=computed(()=>{if(!d.value.brain.url.trim())return {url:'',error:''};try{return {url:profileShareLink(d.value.brain.url),error:''};}catch(e){return {url:'',error:e.message};}});
const sampleKind=ref('text'),sampleAssetId=ref(''),videoPicker=ref(false);
const reviewId=ref('');
const sampleAsset=computed(()=>state.value.assets.find(asset=>asset.id===sampleAssetId.value));
const sampleDialog=ref(false),sampleName=ref(''),sampleText=ref(''),sampleTarget=ref(''),sampleMode=ref('shallow'),detailId=ref(''),topicId=ref(''),copiesId=ref(''),selected=ref(0),requirement=ref(''),deleting=ref(''),error=ref('');
const find=id=>state.value.brains.find(b=>b.id===id),detail=computed(()=>find(detailId.value)),topic=computed(()=>find(topicId.value)),copies=computed(()=>find(copiesId.value));
function samples(target){sampleTarget.value=target?.id||'';sampleName.value=target?.name||'';sampleText.value=target?.sampleText||d.value.brain.sampleText||'';sampleMode.value=target?.mode||d.value.brain.mode;sampleAssetId.value=target?(target.sources?.find(source=>source.kind==='local-video')?.assetId||''):(d.value.brain.sampleAssetId||'');sampleKind.value=sampleAssetId.value?'video':'text';error.value='';sampleDialog.value=true;detailId.value='';}
async function importSamples(){try{const assets=await pickFiles('text'),texts=[];for(const a of assets)texts.push(await call('assetText',{id:a.id}));if(texts.length){sampleText.value=[sampleText.value,...texts].filter(Boolean).join('\n\n');await refresh();}}catch(e){error.value=e.message;}}
async function study(local=false,brainId){
 error.value='';if(local){if(!sampleName.value.trim())return error.value='请填写档案名称';if(sampleKind.value==='video'){if(!sampleAsset.value||sampleAsset.value.type!=='video')return error.value='请选择学习视频';d.value.brain.sampleAssetId=sampleAssetId.value;d.value.brain.sampleText='';}else{if(sampleText.value.trim().length<80)return error.value='请提供至少80字的真实样本文案';if(sampleText.value.length>30000)return error.value='样本文案最多30000字';delete d.value.brain.sampleAssetId;d.value.brain.sampleText=sampleText.value;}d.value.brain.mode=sampleMode.value;}
 else if(!brainId){if(!d.value.brain.url.trim())return notify('请粘贴账号主页分享文字或链接，或导入本地学习样本');if(profileLink.value.error)return notify(profileLink.value.error,'error');if(!collectionConfigured.value)return notify(brainCollectionUnavailable,'warning');delete d.value.brain.sampleAssetId;d.value.brain.sampleText='';}
 const id=d.value.id,result=await act('学习IP风格',()=>call('brainStudy',{id,brainId:brainId||(local?sampleTarget.value:undefined),name:local?sampleName.value:undefined}));
 if(result?.stale)return notify('样本或任务已变化，结果保留在执行记录中，未覆盖当前档案');
 if(result){await refresh(d.value.id===id);sampleDialog.value=false;const c=result.brain?.collection;notify(c?`已学习 ${c.successCount}/${c.requestedCount} 条${c.basis==='caption'?'发布文案':'口播文案'}${c.failed.length?'，'+c.failed.length+'条未提取成功':''}，可在分析中核对来源`:'已生成风格分析，请核对样本依据后使用',c&&!c.complete?'warning':'success');}
}
async function select(b){const r=await act('选用IP档案',()=>call('selectBrain',{id:d.value.id,brainId:b.id}));if(r)await refresh(true);}
async function clear(){delete d.value.brain.activeId;delete d.value.brain.analysis;delete d.value.brain.analysisRevision;delete d.value.brain.selection;await save();}
async function topics(b){topicId.value=b.id;copiesId.value='';requirement.value=b.topics?.requirement||'';if(!b.topics)await generateTopics();}
async function generateTopics(){const id=topicId.value,r=await act('生成IP选题',()=>call('brainTopics',{id:d.value.id,brainId:id,requirement:requirement.value}));if(r?.stale)notify('档案或输入已变化，本次选题未覆盖当前内容');}
async function generateCopies(index){const b=topic.value,r=await act('生成3条口播方案',()=>call('brainCopies',{id:d.value.id,brainId:b.id,topicId:b.topics.id,index}));if(r?.stale)return notify('选题或输入已变化，本次文案未覆盖当前内容');if(r){copiesId.value=b.id;topicId.value='';selected.value=0;}}
async function useCopy(){const b=copies.value,r=await act('使用口播文案',()=>call('useBrainCopy',{id:d.value.id,brainId:b.id,candidateId:b.candidates.id,index:selected.value}));if(r){await refresh(true);copiesId.value='';notify('已将所选方案放入第二步原文案，可继续改写或确认使用','success');}}
function backToTopics(){const b=copies.value;copiesId.value='';if(b)topics(b);}
function reopenCopies(){const b=topic.value;if(!b?.candidates||b.candidates.topicId!==b.topics?.id)return;copiesId.value=b.id;topicId.value='';selected.value=0;}
async function remove(){const r=await act('删除学习档案',()=>call('deleteBrain',{brainId:deleting.value}));if(r)deleting.value='';}
function reStudy(b){samples(b);}
</script>
<template>
 <div class="two-columns brain-columns brain-studio">
  <article class="card brain-form"><div class="brain-fields"><div class="brain-form-heading"><h3>添加对标账号</h3><button class="text-button brain-local-entry" :disabled="!!busy" @click="samples()">导入本地学习样本</button></div><p class="hint">粘贴账号主页的整段分享文字或链接，采集真实作品文案后学习选题与写作风格。</p><label>对标账号主页<input v-model="d.brain.url" aria-label="对标账号主页" aria-describedby="brain-link-feedback" :aria-invalid="!!profileLink.error" maxlength="10000" placeholder="粘贴账号主页分享文字或链接"/></label><p id="brain-link-feedback" class="brain-link-feedback" :class="{'brain-error':!!profileLink.error}" aria-live="polite">{{profileLink.error||(profileLink.url?'已识别链接：'+profileLink.url:'支持整段抖音分享文字；仅有抖音号无法采集。')}}</p><div v-if="!collectionConfigured" class="brain-collection-notice" role="status"><strong>账号主页采集尚未配置</strong><p>当前不能自动获取该账号的作品文案。可先导入本地文案或视频样本，也可在模型设置中配置“账号主页文案采集接口”。</p><button :disabled="!!busy" @click="navigate('settings')">打开设置</button></div><div v-if="localCollection&&!externalCollection" class="brain-collection-notice" role="status"><strong>本地静默采集已启用</strong><p>最多学习 {{sampleLimit}} 条公开作品文案。{{d.brain.profileSource==='caption'?'只分析作者发布的标题与配文，不含视频口播、字幕或画面。':'从音轨识别口播正文，未识别到有效语音的作品会跳过。'}}</p></div><label v-if="localCollection&&!externalCollection" class="brain-content-source">学习内容<select :value="d.brain.profileSource||'audio'" aria-label="账号学习内容" :disabled="!!busy" @change="d.brain.profileSource=$event.target.value"><option value="audio">口播文案（识别视频音轨）</option><option value="caption">发布文案（标题与配文，适合无口播账号）</option></select></label><span class="study-mode-label">学习模式</span><div class="study-modes"><button v-for="[mode,title,description] in [['shallow','浅度学习','学习选题和基础写作风格'],['deep','深度学习','深度学习文案结构与表达习惯']]" :key="mode" :class="{active:d.brain.mode===mode}" :aria-pressed="d.brain.mode===mode" @click="d.brain.mode=mode"><strong>{{title}}</strong><small>{{description}}</small></button></div></div><button class="primary full" :disabled="!!busy||!collectionConfigured" :title="collectionConfigured?'':'请先配置账号主页采集，或使用上方的本地学习样本入口'" @click="study()"><I name="Plus"/>{{collectionConfigured?'添加并学习':'配置采集服务后学习'}}</button>
  </article>
  <article class="card brain-library"><div class="card-heading"><h3>已添加档案</h3><small>{{state.brains.length}} 个</small></div>
   <div v-if="state.brains.length" class="brain-profile-list"><article v-for="b in state.brains" :key="b.id" class="brain-profile" :class="{selected:d.brain.activeId===b.id}"><header><span class="brain-profile-icon"><I name="Database" :size="22"/></span><div><h4>{{b.name}}</h4><p>{{b.mode==='deep'?'深度学习':'浅度学习'}} · {{b.status==='learned'?'已学习':'待学习'}}</p></div><button class="icon-button" :aria-label="'删除档案'+b.name" :disabled="!!busy" @click="deleting=b.id"><I name="Trash2" :size="16"/></button></header><p v-if="b.collection" class="hint">{{b.collection.basis==='caption'?'发布文案':'口播文案'}} {{b.collection.successCount}} / {{b.collection.requestedCount}} 条 · {{b.collection.complete?'已完成本次采样':'部分采样'}}</p><p v-if="b.analysis" class="brain-profile-summary">{{b.analysis.summary}}</p><div class="brain-profile-actions"><button v-if="!b.analysis" :disabled="!!busy" @click="samples(b)">导入样本并学习</button><button :disabled="!b.analysis||!!busy" @click="detailId=b.id">查看分析</button><button :disabled="!b.analysis||!!busy" @click="topics(b)">选题创作</button><button :disabled="!b.analysis||!!busy" :class="{primary:d.brain.activeId===b.id}" @click="select(b)">{{d.brain.activeId===b.id?'已选用':'选用'}}</button></div></article></div>
   <div v-else class="empty-state"><span class="brain-empty-icon"><I name="Lightbulb" :size="36"/></span><h3>暂无 IP 大脑档案</h3><p>左侧添加后会显示在这里。</p></div>
   <button v-if="d.brain.activeId" class="text-button brain-clear" :disabled="!!busy" @click="clear">解除当前档案选用</button>
  </article>
 </div>
 <Modal v-if="sampleDialog" title="导入学习样本" variant="brain-samples" wide @close="sampleDialog=false">
  <p class="hint">选择明确提供的文案或视频进行学习。视频深度学习结合音轨转写与三处画面采样，未覆盖全片镜头。</p>
  <div class="brain-source-tabs" role="group" aria-label="学习样本类型"><button v-for="[kind,title] in [['text','文案样本'],['video','视频样本']]" :key="kind" :aria-pressed="sampleKind===kind" :class="{active:sampleKind===kind}" :disabled="!!busy" @click="sampleKind=kind">{{title}}</button></div>
  <label>档案名称<input v-model="sampleName" aria-label="学习档案名称" :disabled="!!busy" maxlength="60" placeholder="为这组学习样本命名"/></label>
  <template v-if="sampleKind==='text'"><div class="brain-sample-heading"><label for="brain-sample-text">学习样本文案</label><button :disabled="!!busy" @click="importSamples"><I name="Upload" :size="16"/>导入文本</button></div><textarea id="brain-sample-text" v-model="sampleText" :disabled="!!busy" aria-label="学习样本文案" maxlength="30000" placeholder="粘贴至少80字的真实文案；可合并多篇同风格文案"/><small>{{sampleText.length}} / 30000 字</small></template>
  <template v-else><div class="brain-sample-heading"><strong>学习视频</strong><button :disabled="!!busy" @click="videoPicker=true"><I name="Video" :size="16"/>选择视频</button></div><div class="brain-video-selection"><I name="Video" :size="22"/><div><strong>{{sampleAsset?.name||'尚未选择视频'}}</strong><small>{{sampleAsset?(find(sampleTarget)?.sources?.some(source=>source.assetId===sampleAssetId&&source.media?.reviewedTranscription)?'沿用同一视频的校对文字，重新分析写法与所选画面范围。':'会重新识别该视频音轨，不沿用素材描述作为学习结果。'):'从素材库选择或导入本地口播视频。'}}</small></div><button v-if="sampleAsset" class="text-button" :disabled="!!busy" @click="sampleAssetId=''">移除</button></div></template>
  <label>学习模式<select v-model="sampleMode" aria-label="样本学习模式" :disabled="!!busy"><option value="shallow">浅度学习</option><option value="deep">深度学习</option></select></label><p class="hint brain-video-hint">{{sampleKind==='video'?(sampleMode==='deep'?'识别音轨，并观察视频15%、50%、85%位置的三处画面；分析中可查看采样范围。':'识别音轨，分析转写文案的选题与表达方式；不分析画面。'):'仅根据文案分析写作风格，不把文字分析当成视频画面学习。'}}</p>
  <p v-if="error" class="brain-error" role="alert">{{error}}</p><template #footer><button @click="sampleDialog=false">取消</button><button class="primary" :disabled="!!busy" @click="study(true)">开始学习</button></template>
 </Modal>
 <AssetPicker v-if="videoPicker" kind="video" title="选择IP学习视频" @close="videoPicker=false" @select="asset=>{sampleAssetId=asset.id;videoPicker=false;}"/>
 <BrainTranscriptReview v-if="reviewId&&find(reviewId)" :profile="find(reviewId)" @close="reviewId=''" @saved="reviewId=''"/>
 <Modal v-if="detail" title="IP风格分析" variant="brain-detail" wide @close="detailId=''"><div class="brain-analysis-heading"><strong>{{detail.name}}</strong><span>{{detail.sampleText?.length||detail.sampleLength||0}} 字样本 · {{detail.sources?.[0]?.kind==='local-video'?'本地视频':detail.sources?.[0]?.url?'采集文案':'本地文案'}}</span></div><p class="brain-review-note" role="status">以下为模型分析，尚未经人工确认。请核对转写错字、采样范围和推断；样本中的商品表述不代表已验证的事实。</p><section v-if="detail.collection" class="brain-analysis-section brain-profile-evidence"><h4>账号采样范围</h4><p>已学习 {{detail.collection.successCount}} / {{detail.collection.requestedCount}} 条；本次主页可读 {{detail.collection.profile.visibleCount}} 条视频。</p><p class="hint">{{detail.collection.limitation}}</p><p v-if="detail.collection.profile.loginLimited" class="hint">平台提示登录后可查看更多作品，本次仅采集已公开显示的列表。</p><details v-if="detail.collection.failed.length"><summary>查看未成功提取的 {{detail.collection.failed.length}} 条作品</summary><p v-for="row in detail.collection.failed" :key="row.url">{{row.title}}：{{row.error}}</p></details></section><section v-for="source in detail.sources?.filter(source=>['profile-video','profile-caption'].includes(source.kind))" :key="source.url" class="brain-analysis-section brain-profile-evidence"><h4>{{source.title}}</h4><p class="hint">{{source.url}} · {{source.kind==='profile-caption'?'作者发布文案':Number(source.media.duration).toFixed(1)+'秒 · 音轨转写'}}</p><details><summary>查看该作品学习文案</summary><p class="brain-source-text">{{source.text}}</p></details></section><section v-for="source in detail.sources?.filter(source=>source.kind==='local-video')" :key="source.assetId" class="brain-analysis-section brain-video-evidence"><h4>视频学习依据</h4><p>{{source.title}} · {{Number(source.media.duration).toFixed(2)}} 秒</p><p v-if="source.media.visual" class="hint">采样位置：{{source.media.visual.sampledAt.map(time=>time+'秒').join('、')}}；仅覆盖这三处画面。</p><p v-else class="hint">本次浅度学习仅使用音轨转写，未分析画面。</p><div v-if="source.media.visual" class="brain-analysis-summary"><h3>采样画面观察</h3><p>{{source.media.visual.description}}</p><small>{{source.media.visual.limitation}}</small></div><details v-if="source.media.reviewedTranscription"><summary>查看校对后转写</summary><p v-for="(segment,index) in source.media.reviewedTranscription.segments" :key="index"><small>{{segment.start.toFixed(2)}}–{{segment.end.toFixed(2)}} 秒</small> {{segment.text}}</p></details><details><summary>查看原始转写时间轴</summary><p v-for="(segment,index) in source.media.transcription.segments" :key="index"><small>{{segment.start.toFixed(2)}}–{{segment.end.toFixed(2)}} 秒</small> {{segment.text}}</p></details></section><section class="brain-analysis-summary"><h3>风格分析</h3><p>{{detail.analysis?.summary}}</p></section><section v-for="[key,title] in [['tone','表达语气'],['structure','内容结构'],['strengths','表达特点'],['avoid','应避免的写法'],['topicAngles','选题方向']]" :key="key" class="brain-analysis-section"><h4>{{title}}</h4><ul><li v-for="item in detail.analysis?.[key]" :key="item">{{item}}</li></ul></section><section class="brain-analysis-section"><h4>样本依据</h4><blockquote v-for="item in detail.analysis?.evidence" :key="item.quote"><p>{{item.quote}}</p><small>{{item.point}}</small></blockquote></section><template #footer><button :disabled="!!busy" @click="reStudy(detail)">重新学习</button><button v-if="detail.sources?.some(source=>source.kind==='local-video'&&source.media?.transcription?.segments?.length)" :disabled="!!busy" @click="reviewId=detail.id">校对转写</button><button class="primary" :disabled="!!busy" @click="topics(detail);detailId=''">生成选题</button></template></Modal>
 <Modal v-if="topic" title="IP选题分析" variant="brain-topics" wide @close="topicId=''"><section class="brain-analysis-summary"><h3><I name="Lightbulb" :size="16"/>风格分析</h3><p>{{topic.analysis?.summary}}</p></section><label>创作要求<input v-model="requirement" aria-label="IP创作要求" maxlength="1500" placeholder="可填写你的行业、受众或本次主题"/></label><div class="brain-topic-heading"><h4>推荐选题</h4><button class="text-button" :disabled="!!busy" @click="generateTopics"><I name="RefreshCw" :size="15"/>换一批</button></div><div class="brain-topic-list"><button v-for="(item,index) in topic.topics?.items" :key="index" :disabled="!!busy" @click="generateCopies(index)"><span>{{index+1}}</span><div><strong>{{item.title}}</strong><small>{{item.angle}}</small></div><em>去创作</em></button><p v-if="!topic.topics" class="hint">{{busy?'正在生成选题，请稍候…':'暂无选题，请点击换一批。'}}</p></div><template #footer><WordLimit v-model="d.wordLimit"/><button v-if="topic.candidates?.topicId===topic.topics?.id" :disabled="!!busy" @click="reopenCopies">查看已生成文案</button><button @click="topicId=''">关闭</button></template></Modal>
 <Modal v-if="copies" title="IP口播文案" variant="brain-copies" wide @close="copiesId=''"><div class="brain-copy-grid" role="group" aria-label="IP口播方案"><button v-for="(item,index) in copies.candidates?.items" :key="index" class="brain-copy-card" :class="{selected:selected===index}" :aria-pressed="selected===index" @click="selected=index"><header><strong>方案 {{index+1}}</strong><span>已生成</span></header><h4>{{item.title}}</h4><p>{{item.text}}</p><small>{{item.text.length}} 字</small></button></div><template #footer><button @click="backToTopics">返回选题</button><button class="primary" :disabled="!!busy" @click="useCopy">使用此文案</button></template></Modal>
 <Modal v-if="deleting" title="删除学习档案" @close="deleting=''"><p>删除“{{find(deleting)?.name}}”？已选用的档案需要先解除选用。</p><template #footer><button @click="deleting=''">取消</button><button class="danger-button" :disabled="!!busy" @click="remove">删除</button></template></Modal>
</template>
